function demoMatches(
  r: DemoRegime,
  npop: number,
  vs: number,
  zStar: number,
  simpsonC: number,
  alpha0: number,
): boolean {
  if (r.npop !== npop) return false;
  if (Math.abs(r.vs - vs) > 1e-6) return false;
  if (Math.abs(r.zStar - zStar) > 1e-6) return false;
  if (r.scaling === "c") return Math.abs((r.c ?? 0) - simpsonC) < 0.005;
  return Math.abs((r.alpha0 ?? 0) - alpha0) < 1e-9;
}

function clampNpop(value: number): number {
  const x = Number(value);
  if (!Number.isFinite(x)) return NPOP_DEFAULT;
  return Math.min(NPOP_MAX, Math.max(NPOP_MIN, Math.round(x)));
}

function clampAlpha(value: number): number {
  const x = Number(value);
  if (!Number.isFinite(x)) return ALPHA_DEFAULT;
  return Math.min(ALPHA_MAX, Math.max(ALPHA_MIN, x));
}

function alphaToSlider(a: number): number {
  const t = Math.log(a / ALPHA_MIN) / Math.log(ALPHA_MAX / ALPHA_MIN);
  return Math.round(ALPHA_SLIDER_STEPS * Math.min(1, Math.max(0, t)));
}

function sliderToAlpha(t: number): number {
  return clampAlpha(
    ALPHA_MIN * (ALPHA_MAX / ALPHA_MIN) ** (Number(t) / ALPHA_SLIDER_STEPS),
  );
}

function clampAlpha0(value: number): number {
  const x = Number(value);
  if (!Number.isFinite(x)) return ALPHA0_DEFAULT;
  return Math.min(ALPHA0_MAX, Math.max(ALPHA0_MIN, x));
}

function alpha0ToSlider(a: number): number {
  const t = Math.log(a / ALPHA0_MIN) / Math.log(ALPHA0_MAX / ALPHA0_MIN);
  return Math.round(ALPHA0_SLIDER_STEPS * Math.min(1, Math.max(0, t)));
}

function sliderToAlpha0(t: number): number {
  return clampAlpha0(
    ALPHA0_MIN * (ALPHA0_MAX / ALPHA0_MIN) ** (Number(t) / ALPHA0_SLIDER_STEPS),
  );
}

function logAlphaFromAlpha0(alpha0: number, n: number): number {
  return Math.log(alpha0) - n * Math.LN2;
}

function formatSci(x: number, digits = 2): string {
  if (!Number.isFinite(x)) return "—";
  if (x === 0) return "0";
  const ax = Math.abs(x);
  if (ax >= 1 && ax < 10000) return x.toFixed(ax >= 100 ? 0 : 2);
  if (ax >= 0.01 && ax < 1) return x.toFixed(3);
  return x.toExponential(digits);
}

function impliedAlpha0(alpha: number, n: number): number {
  const l = Math.log(alpha) + n * Math.LN2;
  return l > 700 ? Infinity : Math.exp(l);
}

function impliedAlpha(alpha0: number, n: number): number {
  return Math.exp(logAlphaFromAlpha0(alpha0, n));
}

function clampSimpson(value: number): number {
  const x = Number(value);
  if (!Number.isFinite(x)) return SIMPSON_DEFAULT;
  return Math.min(SIMPSON_MAX, Math.max(SIMPSON_MIN, x));
}

function simpsonToSlider(c: number): number {
  return Math.round(
    SIMPSON_SLIDER_STEPS * ((c - SIMPSON_MIN) / (SIMPSON_MAX - SIMPSON_MIN)),
  );
}

function sliderToSimpson(t: number): number {
  return clampSimpson(
    SIMPSON_MIN + (Number(t) / SIMPSON_SLIDER_STEPS) * (SIMPSON_MAX - SIMPSON_MIN),
  );
}

/** Lower bound 1/K: Dirichlet E[Σ x_g²] → 1/K as α → ∞. */
function simpsonFloor(n: number): number {
  if (n >= 50) return 0;
  return 2 ** -n;
}

function expectedSimpson(alpha: number, n: number, logAlpha?: number): number {
  const la =
    logAlpha !== undefined && Number.isFinite(logAlpha)
      ? logAlpha
      : Math.log(alpha);
  if (!Number.isFinite(la)) return NaN;
  const alpha0 = Math.exp(la + n * Math.LN2);
  const a = Math.exp(la);
  if (!Number.isFinite(alpha0)) return 0;
  if (!(a > 0) || !Number.isFinite(a)) return 1 / (alpha0 + 1);
  return (a + 1) / (alpha0 + 1);
}

/**
 * α(K) = (1−c)/(cK − 1) so E[S(X)] = c exactly on Dirichlet(α,…,α), K=2ⁿ.
 */
function alphaFromSimpson(
  c: number,
  n: number,
): { ok: true; logAlpha: number; alpha: number; alpha0: number } | { ok: false } {
  const floor = simpsonFloor(n);
  if (!(c > floor && c < 1)) return { ok: false };
  if (n >= 50) {
    const logAlpha = Math.log(1 - c) - Math.log(c) - n * Math.LN2;
    return { ok: true, logAlpha, alpha: Math.exp(logAlpha), alpha0: (1 - c) / c };
  }
  const K = 2 ** n;
  const den = c * K - 1;
  if (den <= 0) return { ok: false };
  const a = (1 - c) / den;
  if (!(a > 0) || !Number.isFinite(a)) return { ok: false };
  return { ok: true, logAlpha: Math.log(a), alpha: a, alpha0: K * a };
}

function mulberry32(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s += 0x6d2b79f5;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function randn(rng: () => number): number {
  const u = Math.max(rng(), 1e-12);
  const v = Math.max(rng(), 1e-12);
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

function randGamma(a: number, rng: () => number): number {
  if (a < 1) {
    const u = Math.max(rng(), 1e-12);
    return randGamma(a + 1, rng) * u ** (1 / a);
  }
  const d = a - 1 / 3;
  const c = 1 / Math.sqrt(9 * d);
  for (;;) {
    let x = 0;
    let v = 0;
    do {
      x = randn(rng);
      v = 1 + c * x;
    } while (v <= 0);
    v = v * v * v;
    const u = rng();
    if (u < 1 - 0.0331 * x * x * x * x) return d * v;
    if (Math.log(u) < 0.5 * x * x + d * (1 - v + Math.log(v))) return d * v;
  }
}

function logBinoms(n: number): number[] {
  const L = new Array<number>(n + 1);
  L[0] = 0;
  for (let k = 1; k <= n; k++) {
    L[k] = L[k - 1] + Math.log(n - k + 1) - Math.log(k);
  }
  return L;
}

function omegaLayers(n: number, vs: number, zStar: number): number[] {
  const w = new Array<number>(n + 1);
  for (let k = 0; k <= n; k++) {
    const d = k / n - zStar;
    w[k] = Math.exp(-(d * d) / (2 * vs));
  }
  return w;
}

/** Dirichlet(α C(n,0), …, α C(n,n)): Hamming-layer masses of Dirichlet(α,…,α). */
function sampleLayerDirichlet(
  n: number,
  logAlpha: number,
  logB: number[],
  rng: () => number,
): number[] {
  const m = n + 1;
  const logg = new Array<number>(m);
  for (let k = 0; k < m; k++) {
    const logA = logAlpha + logB[k];
    if (logA > 700) {
      logg[k] = logA;
    } else if (logA > 20) {
      const ak = Math.exp(logA);
      logg[k] = Math.log(Math.max(ak + Math.sqrt(ak) * randn(rng), 1e-300));
    } else if (logA < -40) {
      logg[k] = -1e9;
    } else {
      logg[k] = Math.log(Math.max(randGamma(Math.exp(logA), rng), 1e-300));
    }
  }
  let maxL = -Infinity;
  for (let k = 0; k < m; k++) if (logg[k] > maxL) maxL = logg[k];
  let s = 0;
  const x = new Array<number>(m);
  for (let k = 0; k < m; k++) {
    x[k] = Math.exp(logg[k] - maxL);
    s += x[k];
  }
  const inv = 1 / s;
  for (let k = 0; k < m; k++) x[k] *= inv;
  return x;
}

/** p log₂(p/q). Zero if p is numerically 0. Every KL and C(x) uses this base. */
function klTerm2(p: number, q: number): number {
  if (p <= 1e-18) return 0;
  return p * Math.log2(p / Math.max(q, 1e-300));
}

type BoltzResult = {
  /** D_KL(ψ* ‖ φ*) in bits (log₂). */
  D: number;
  /** ⟨C⟩_* in bits; C(x) = D_KL(x′ ‖ x) with log₂. */
  C: number;
  eta: number;
  ess: number;
  samples: number;
  meanLogW: number;
  meanW: number;
  F: number;
  /** Neutral individual-trait masses P_φ(Z=k/n) = C(n,k)/2^n. */
  phiZ: number[];
  /** Selected individual-trait masses P_ψ(Z=k/n) = E_ψ[X_k]. */
  psiZ: number[];
  meanZPhi: number;
  meanZPsi: number;
  /** D_KL(ψ^Z ‖ φ^Z) in bits. */
  klZ: number;
};

function boltzmannMaint(
  n: number,
  vs: number,
  zStar: number,
  Npop: number,
  logAlpha: number,
  seedTag: number,
): BoltzResult | null {
  if (n < 1 || n > N_MAX) return null;
  const layers = n + 1;
  const omega = omegaLayers(n, vs, zStar);
  const logB = logBinoms(n);
  const samples = n <= 20 ? 4000 : 2500;
  const rng = mulberry32(
    (n * 10007 +
      Math.round(vs * 1e6) +
      Math.round(zStar * 1e4) +
      Npop * 13 +
      Math.round(logAlpha * 1e6) +
      seedTag * 99991) >>>
      0,
  );
  const logTilt = new Array<number>(samples);
  const meanFit = new Array<number>(samples);
  const C = new Array<number>(samples);
  const layerMass = new Array<number[]>(samples);
  let maxLt = -Infinity;
  for (let s = 0; s < samples; s++) {
    const x = sampleLayerDirichlet(n, logAlpha, logB, rng);
    layerMass[s] = x;
    let W = 0;
    for (let k = 0; k < layers; k++) W += x[k] * omega[k];
    W = Math.max(W, 1e-300);
    meanFit[s] = W;
    const lt = 2 * Npop * Math.log(W); // nats for W^{2N}; KL is reported in bits
    logTilt[s] = lt;
    if (lt > maxLt) maxLt = lt;
    let cost = 0;
    for (let k = 0; k < layers; k++) {
      const r = Math.max(omega[k] / W, 1e-300);
      const xp = x[k] * r;
      cost += klTerm2(xp, Math.max(x[k], 1e-300));
    }
    C[s] = cost;
  }
  let sumExp = 0;
  for (let s = 0; s < samples; s++) {
    sumExp += Math.exp(logTilt[s] - maxLt);
  }
  let essInv = 0;
  let eLogTilt = 0;
  let eC = 0;
  let eW = 0;
  const psiZ = new Array<number>(layers).fill(0);
  const phiZ = new Array<number>(layers);
  const logK = n * Math.LN2;
  for (let k = 0; k < layers; k++) phiZ[k] = Math.exp(logB[k] - logK);
  for (let s = 0; s < samples; s++) {
    const ps = Math.exp(logTilt[s] - maxLt) / sumExp;
    essInv += ps * ps;
    eLogTilt += ps * logTilt[s];
    eC += ps * C[s];
    eW += ps * meanFit[s];
    const x = layerMass[s];
    for (let k = 0; k < layers; k++) psiZ[k] += ps * x[k];
  }
  let meanZPhi = 0;
  let meanZPsi = 0;
  let klZ = 0;
  for (let k = 0; k < layers; k++) {
    const z = k / n;
    meanZPhi += phiZ[k] * z;
    meanZPsi += psiZ[k] * z;
    const p = Math.max(psiZ[k], 0);
    const q = Math.max(phiZ[k], 1e-300);
    klZ += klTerm2(p, q);
  }
  const logZ = maxLt + Math.log(sumExp / samples);
  const twoN = 2 * Npop;
  const Dbits = (eLogTilt - logZ) / Math.LN2; // D_KL(ψ* ‖ φ*) in bits = nats / ln 2
  const meanLogW = eLogTilt / twoN;
  const F = logZ / twoN;
  const eta = eC > 1e-18 ? Dbits / (twoN * eC) : NaN;
  return {
    D: Dbits,
    C: eC,
    eta,
    ess: 1 / essInv,
    samples,
    meanLogW,
    meanW: eW,
    F,
    phiZ,
    psiZ,
    meanZPhi,
    meanZPsi,
    klZ,
  };
}

function isArrowKey(key: string): boolean {
  return (
    key === "ArrowLeft" ||
    key === "ArrowRight" ||
    key === "ArrowUp" ||
    key === "ArrowDown"
  );
}

function arrowDelta(key: string, shift: boolean, step: number): number {
  const dir = key === "ArrowRight" || key === "ArrowUp" ? 1 : -1;
  return dir * step * (shift ? 10 : 1);
}

function bump(value: number, min: number, max: number, delta: number): number {
  return Math.min(max, Math.max(min, value + delta));
}

function ArmRange({
  id,
  armed,
  setArmed,
  min,
  max,
  step,
  value,
  onChange,
  label,
  accent,
  width = 220,
}: {
  id: string;
  armed: string;
  setArmed: (id: string) => void;
  min: number;
  max: number;
  step: number;
  value: number;
  onChange: (v: number) => void;
  label: string;
  accent: string;
  width?: number;
}) {
  return (
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={(e: { currentTarget: { value: string } }) =>
        onChange(Number(e.currentTarget.value))
      }
      onPointerDown={() => setArmed(id)}
      onFocus={() => setArmed(id)}
      onKeyDown={(e: { key: string; preventDefault: () => void }) => {
        if (isArrowKey(e.key)) e.preventDefault();
      }}
      aria-label={label}
      style={{
        width,
        accentColor: accent,
        cursor: "pointer",
        outline: armed === id ? `2px solid ${accent}` : "none",
        outlineOffset: 3,
      }}
    />
  );
}

function peakOf(y: number[]): number {
  let m = 1e-12;
  for (let i = 0; i < y.length; i++) if (y[i] > m) m = y[i];
  return m;
}

function scaleToPeak(y: number[], peak: number): number[] {
  const out = new Array<number>(y.length);
  for (let i = 0; i < y.length; i++) out[i] = y[i] / peak;
  return out;
}

function fmtPeak(x: number): string {
  return x >= 0.01 ? x.toFixed(3) : x.toExponential(2);
}

function binTrait(
  n: number,
  phiZ: number[],
  psiZ: number[],
  maxBins: number,
): { z: number[]; phi: number[]; psi: number[] } {
  const m = n + 1;
  if (m <= maxBins) {
    const z = new Array<number>(m);
    const phi = new Array<number>(m);
    const psi = new Array<number>(m);
    for (let k = 0; k < m; k++) {
      z[k] = k / n;
      phi[k] = phiZ[k] * n;
      psi[k] = psiZ[k] * n;
    }
    return { z, phi, psi };
  }
  const z: number[] = [];
  const phi: number[] = [];
  const psi: number[] = [];
  for (let i = 0; i < maxBins; i++) {
    const k0 = Math.floor((i * m) / maxBins);
    const k1 = Math.floor(((i + 1) * m) / maxBins);
    const dk = k1 - k0;
    if (dk <= 0) continue;
    let p = 0;
    let q = 0;
    for (let k = k0; k < k1; k++) {
      p += phiZ[k];
      q += psiZ[k];
    }
    z.push((k0 + k1 - 1) / (2 * n));
    phi.push((p * n) / dk);
    psi.push((q * n) / dk);
  }
  return { z, phi, psi };
}

function polylinePts(
  z: number[],
  y: number[],
  left: number,
  top: number,
  innerW: number,
  innerH: number,
  ymax: number,
): string {
  const pts: string[] = [];
  for (let i = 0; i < z.length; i++) {
    const x = left + z[i] * innerW;
    const yy = top + (1 - y[i] / ymax) * innerH;
    pts.push(`${x},${yy}`);
  }
  return pts.join(" ");
}

