/** Stabilizing Gaussian: W = exp[−(z − z*)² / (2 Vs)], W_max = 1. */
function fitnessW(z: number, vs: number, zStar: number): number {
  const d = z - zStar;
  return Math.exp(-(d * d) / (2 * vs));
}

/** Fitness W ∈ (0, 1] → red (bad) to green (good). */
function fitnessFill(w: number): string {
  const t = Math.max(0, Math.min(1, w));
  const r = Math.round(196 * (1 - t) + 42 * t);
  const g = Math.round(48 * (1 - t) + 150 * t);
  const b = Math.round(48 * (1 - t) + 74 * t);
  return `rgb(${r}, ${g}, ${b})`;
}

function luminance(fill: string): number {
  const m = fill.match(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/);
  if (!m) return 128;
  return 0.299 * Number(m[1]) + 0.587 * Number(m[2]) + 0.114 * Number(m[3]);
}

